mapper.select:
select count(1)
from lab_reservation r
where r.lab_id = coalesce(
        #{reservation.labId},
        (
            select id
            from lab
            where lab_name = #{reservation.labName}
               or concat(lab_code, ' ', lab_name) = #{reservation.labName}
               or lab_code = substring_index(#{reservation.labName}, ' ', 1)
            limit 1
        ),
        r.lab_id
    )
  and r.reservation_date = #{reservation.reservationDate}
  and (
        time_to_sec(str_to_date(substring_index(#{reservation.timeRange}, '-', 1), '%H:%i')) / 60
      ) < (
        time_to_sec(str_to_date(substring_index(r.time_range, '-', -1), '%H:%i')) / 60
      )
  and (
        time_to_sec(str_to_date(substring_index(r.time_range, '-', 1), '%H:%i')) / 60
      ) < (
        time_to_sec(str_to_date(substring_index(#{reservation.timeRange}, '-', -1), '%H:%i')) / 60
      )
  and r.status not in ('已驳回', '已取消')
  and (#{id} is null or r.id <> #{id})

select count(1)
from lab_reservation
where lab_id = #{labId}
  and status = '已通过'
  and (
        reservation_date > curdate()
        or (
            reservation_date = curdate()
            and (
                time_to_sec(str_to_date(substring_index(time_range, '-', -1), '%H:%i')) / 60
            ) >= (time_to_sec(curtime()) / 60)
        )
  )
